import{_ as r,o as a,c as n,a2 as t}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"ADR-003: Pure render(t) and determinism rules","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-pure-render-determinism.md","filePath":"adr/003-pure-render-determinism.md"}'),d={name:"adr/003-pure-render-determinism.md"};function i(s,e,o,c,l,m){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-003-pure-render-t-and-determinism-rules" tabindex="-1">ADR-003: Pure render(t) and determinism rules <a class="header-anchor" href="#adr-003-pure-render-t-and-determinism-rules" aria-label="Permalink to &quot;ADR-003: Pure render(t) and determinism rules&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-15</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The visual state is a pure function of <code>(timeline, t)</code>:</p><ul><li>no wall clock, no CSS animations/transitions (forced off by the base stylesheet), no <code>Math.random</code>;</li><li>randomness comes from seeded hashes (<code>rnd(seed)</code>, <code>mulberry32</code>) keyed by element id and frame index;</li><li>state changes are derived from <code>states[]</code> up to <code>t</code> (with <code>$since</code> times), never accumulated.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Any frame can be rendered in any order by any worker (NFR-4, tested by rendering frames {0, 90, 179} in different orders and comparing SHA-1s).</li><li>Partial re-render and scrubbing in the studio are trivially correct.</li><li>Components must be written as functions of time; a unit test renders the gallery forwards and backwards and compares the DOM.</li></ul>',7)])])}const f=r(d,[["render",i]]);export{h as __pageData,f as default};
